"""Typed response and request models for KEYPOOL Python SDK."""

from __future__ import annotations

from pydantic import BaseModel, ConfigDict, Field


class ChatMessage(BaseModel):
    """Chat completion message."""

    model_config = ConfigDict(extra="allow")

    role: str
    content: str | None = None
    name: str | None = None


class ChatCompletionChoice(BaseModel):
    """Individual choice generated by a model."""

    model_config = ConfigDict(extra="allow")

    index: int = 0
    message: ChatMessage
    finish_reason: str | None = "stop"


class UsageInfo(BaseModel):
    """Token consumption metrics for a completion request."""

    model_config = ConfigDict(extra="allow")

    prompt_tokens: int = 0
    completion_tokens: int = 0
    total_tokens: int = 0
    estimated_cost_usd: float | None = None


class ChatCompletionResponse(BaseModel):
    """Normalized OpenAI-compatible chat completion response."""

    model_config = ConfigDict(extra="allow")

    id: str
    object: str = "chat.completion"
    created: int
    model: str
    provider: str
    choices: list[ChatCompletionChoice] = Field(default_factory=list)
    usage: UsageInfo = Field(default_factory=UsageInfo)


class SelectedKey(BaseModel):
    """Selected credential secret and metadata for SDK callers."""

    model_config = ConfigDict(extra="allow")

    credential_id: str
    provider: str
    secret: str
    masked_secret: str
    env_var_name: str
    profile: str | None = None
    selection_reason: str | None = None


class EmbeddingData(BaseModel):
    """Individual vector embedding."""

    model_config = ConfigDict(extra="allow")

    index: int = 0
    embedding: list[float] = Field(default_factory=list)
    object: str = "embedding"


class EmbeddingUsage(BaseModel):
    """Token usage for embeddings."""

    model_config = ConfigDict(extra="allow")

    prompt_tokens: int = 0
    total_tokens: int = 0
    estimated_cost_usd: float | None = None


class EmbeddingResponse(BaseModel):
    """Normalized embeddings response."""

    model_config = ConfigDict(extra="allow")

    object: str = "list"
    data: list[EmbeddingData] = Field(default_factory=list)
    model: str
    usage: EmbeddingUsage = Field(default_factory=EmbeddingUsage)


class ChatCompletionChunkDelta(BaseModel):
    """Streaming chunk delta content."""

    model_config = ConfigDict(extra="allow")

    role: str | None = None
    content: str | None = None


class ChatCompletionChunkChoice(BaseModel):
    """Streaming chunk choice."""

    model_config = ConfigDict(extra="allow")

    index: int = 0
    delta: ChatCompletionChunkDelta = Field(default_factory=ChatCompletionChunkDelta)
    finish_reason: str | None = None


class ChatCompletionChunk(BaseModel):
    """OpenAI-compatible chat completion chunk for streaming."""

    model_config = ConfigDict(extra="allow")

    id: str
    object: str = "chat.completion.chunk"
    created: int
    model: str
    choices: list[ChatCompletionChunkChoice] = Field(default_factory=list)
